import type { PositionGroup } from "@story-fm/domain";

/**
 * EPL 실선수 스냅샷 — 팀당 23~43인, **2026-27 시즌 개막 시점**
 * (2026-08-18 기준 등록 스쿼드 + 2026 여름 이적. 창은 9월 1일에 닫힌다).
 *
 * 출처는 셋을 교차한다 — 명단·등번호는 위키백과 구단 문서의 1군 등록 스쿼드,
 * 능력치 6축·생년월일·키·체중·주발·약발은 EA FC 27 공개 등급(fcratings),
 * 주급은 공개 급여 자료(salarysport). 어긋나면 **명단은 위키, 나머지는 EA**를
 * 따른다 — 위키가 매일 갱신되는 유일한 축이고, EA는 신체가 대체로 정확하다.
 * **생년월일은 위키가 정한다** — EA도 여기서 틀리고, 그 오류가 조인을 깬다
 * (data/sources.md §4.1). 포지션 코드는 기존 시드(있으면)를 우선한다.
 *
 * **명단·등번호·표기를 2026-08-18에 위키 1군 표와 전수 대조했다** — 시드에 들어가는
 * 것은 1군 절의 행 전부이고, 임대·2군·유스 절과 `Other players under contract`는
 * 넣지 않는다 (data/sources.md §4.1). 임대 선수는 임대처 스쿼드에 있다(§4.1.1).
 *
 * ⚠️ **이 대조에서 늘어난 인원의 6축은 실측이 아니다.** fcratings가 자동 수집을
 * 막아(JS 캡차) 그 자리를 **자리 기준치**로 채웠다 — 같은 구단 같은 포지션군
 * 실선수의 축별 중앙값이고, 신체·주발·약발은 비워 두었다(모르는 것은 비운다).
 * 다음 fcratings 갱신이 덮어야 할 자리다 (sources.md §4.1).
 *
 * ⚠️ **EA에 없는 선수는 옛 값 그대로다.** EA는 구단당 25명 안팎만 싣기 때문에
 * 5대 리그 시드 2,797명 중 2,357명(84%)만 실측 키를 갖고, 나머지 440명은
 * 대부분 아카데미 자원이다(21세 이하가 246명). 이들의 6축은 여전히 판단값이다.
 *
 * ⚠️ **골키퍼의 6축은 EA의 골키퍼 세부 능력치**다. 그래서 `dribbling`(볼컨트롤)·
 * `defending`(수비 위치선정)이 한 자릿수까지 내려간다 — 버그가 아니다. 골키퍼가
 * 실제로 쓰는 축은 `goalkeeping`(EA OVR)과 `passing`(EA Kicking) 둘뿐이고
 * 나머지는 `deriveAxes`가 보지 않는다 (world/attributes.ts).
 *
 * ⚠️ 라이선스 부채 (sources.md §7): 능력치·실명은 EA IP·NIL 대상.
 * MVP 한정 사용 — 정식 출시 전 자체 산정 능력치·가명 전환으로 청산한다.
 *
 * 세계관 주의: 인게임 연도는 가상으로 진행되고, 유스 유입은 계속 합성
 * 가명으로 생성한다 (실존 유소년에게 가상 서사를 입히는 리스크 회피,
 * people.md §2). 강등 팀(레스터·입스위치·사우샘프턴)은 카탈로그 유지를
 * 위해 실제 챔피언십 스쿼드로 채운다 — 카탈로그의 EPL 20팀은 실제 리그
 * 구성이 아니라 이 게임의 1부 명단이다.
 */
export interface RealPlayerSeed {
  /** 로마자 통용 표기 — id 슬러그·외부 데이터 매핑용 */
  nameEn: string;
  /** 한국 축구 언론 통용 한글 표기 — 게임 내 표시명 */
  nameKo: string;
  /** 2026-27 소속팀 등번호. 공식 스쿼드 표에서 확인되지 않으면 생략 */
  squadNumber?: number;
  /** 출생년월일 (YYYY-MM-DD) — 나이는 플레이 날짜 기준 계산 */
  birthdate: string;
  /**
   * `birthdate`가 `YYYY-01-01`일 때만 쓰는 표식 — **연도만 근거가 있고 월·일은
   * 모르는 자리표시자면 `true`, 대조해서 실제 1월 1일생임을 확인했으면 `false`.**
   *
   * 1월 1일은 조사가 닿지 않은 자리를 채우는 값으로 쓰여 왔고(라로 고메스가
   * `2006-01-01`로 실려 있었는데 실제는 2006-10-16), 실제 1월 1일생과 생김새가
   * 같아 표식 없이는 둘을 가르지 못한다. 그래서 **`-01-01`인 시드는 이 필드를
   * 생략할 수 없다** — `test/seed-join.test.ts`가 빠진 것을 잡는다.
   *
   * `true`인 값은 **조인 키가 아니다.** (이름 + 생년월일) 대조에 쓰지 않고,
   * 조인 실패의 "옛 값 유지"도 적용하지 않는다 — 확인된 날짜가 나오면 덮고
   * 이 표식을 지운다 (data/sources.md §4.1).
   */
  birthdateApprox?: boolean;
  /**
   * **위키데이터 QID** — 사람을 가리는 유일한 키. 갱신을 건너 사는 축이라
   * (이름 + 생년월일)이 못 가르는 자리를 여기서 가른다.
   *
   * 채우는 경로는 하나뿐이다: 위키백과 구단 문서 `{{Fs player}}` 행의
   * `name=[[문서 제목]]` → 그 문서의 `wikibase_item`. **문서 제목이 동명이인을
   * 이미 갈라 두었으므로**(`Vitinha (footballer, born March 2000)` ·
   * `Vitinha (footballer, born February 2000)`) 이 경로에서 1:1이 성립한다
   * (data/sources.md §5).
   *
   * ⚠️ **없으면 없는 채로 둔다.** 위키 문서가 없는 아카데미 자원은 QID도
   * 없다 — 지어낸 QID는 없는 것보다 나쁘다. 그 선수의 조인 키는 지금처럼
   * (이름 + 생년월일)이다.
   *
   * ⚠️ **생년월일이 QID를 검증하지 못한다.** 시드의 생년월일은 옛 조인이 남긴
   * 근사치가 섞여 있어(§4.1) QID와 어긋나는 자리가 있고, 그때 틀린 쪽은
   * 생년월일이다. QID의 근거는 구단 문서의 그 행이지 날짜가 아니다.
   */
  wikidataId?: string;
  position: string;
  positionGroup: PositionGroup;
  pace: number;
  shooting: number;
  passing: number;
  dribbling: number;
  defending: number;
  physical: number;
  /** GK 전용 — 종합 overall 수준 */
  goalkeeping?: number;
  potential: number;
  /**
   * 홈그로운 자격 (그 클럽 나라 협회에서 만 21세 이전 3시즌 등록).
   * 시드에 없으면 카탈로그가 결정적 대체 규칙으로 채운다 — sources.md §7.
   */
  homegrown?: boolean;
  /**
   * 키(cm) · 체중(kg) — **실측 등재값**. 주요 선수만 채우고, 없으면 카탈로그가
   * 능력치에서 파생한다(`physiqueOf`). 시드 값이 있으면 언제나 그쪽이 우선이다.
   */
  height?: number;
  weight?: number;
  /**
   * **주발** — 더 잘 쓰는 쪽 (EA FC 27 공개 `Preferred Foot`).
   * 없으면 카탈로그가 주 포지션의 좌우로 추정한다(`footOf` — 데이터 부채).
   */
  foot?: "L" | "R";
  /**
   * **약발 등급 1~5** (EA FC 27 공개 `Weak Foot` 별점 그대로).
   * 생략하면 **4** — 조사가 닿지 않은 선수의 기본값이다.
   *
   * 5대 리그 시드 2,797명 중 2,393명(86%)이 실측이고, 나머지는 EA에 없는
   * 아카데미 자원이라 4로 남는다. **실측이 있으면 3도 그대로 적는다** — 3성은
   * EA 분포의 최빈값(61%)이고, 이걸 4로 접으면 카탈로그가 통째로 "약발 좋은
   * 선수들"이 되어 좌우 배치 판단이 밋밋해진다.
   */
  weakFoot?: number;
  /**
   * 실제 주급 (£/주) — 새 게임의 초기 계약(`CONTRACT`)에 그대로 쓰인다.
   * 공개 자료(salarysport)에 있는 선수는 그 값이고, 없는 아카데미 자원은
   * 같은 자료에서 뽑은 OVR 구간 중앙값으로 어림했다.
   *
   * ⚠️ **승격 팀(코번트리·헐)의 시드는 2부 시절 값이었다** — 최고 연봉자가
   * £40k·£26k/주로, EPL 구단이 아니라 챔피언십 구단의 급여표였다. 실측이라기보다
   * 낡은 값이라 **구단 전체에 ×2.5를 대어 승격 계약으로 갈아입혔다**(개별 선수를
   * 손으로 찍지 않는다). 근거는 이 카탈로그 안에 있다 — 다른 EPL 19팀의 주급/모델
   * 예산 비가 0.75~1.30인데 두 팀만 0.43이었고, 배율 뒤엔 0.97·0.90으로 그 띠에
   * 들어온다. 실제 승격팀(선더랜드 £62.8M/년 · 최고 £115k/주)과도 같은 자리다.
   */
  weeklyWage?: number;
}

